INSERT INTO `entity_comments` VALUES (1,'case',1085,23,'سلام و درود\r\nدندان چسبید و فایل نهایی ارسال شد خدمتتون','2026-08-09 22:04:12','2026-08-09 22:04:12'),(2,'case',1060,23,'سلام و درود\r\nحتما فایل کیس هارو به صورت زیپ ارسال کنید که اینجوری نیاشن و همه 1 فایل باشن ممنون','2026-08-10 16:42:08','2026-08-10 16:42:08'),(3,'case',1098,1,'متصل است.','2026-08-10 18:14:47','2026-08-10 18:14:47'),(4,'case',1110,23,'سلام\r\nکار دندان مقابل ندارد\r\nاحتیاج به طراحی کست هست؟','2026-08-14 13:37:26','2026-08-14 13:37:26'),(8,'case',1101,1,'متصل است','2026-08-15 17:29:11','2026-08-15 17:29:11'),(9,'case',1124,1,'هارمونی با راست مهم است\r\nحتما میرور شود mirror\r\nمتصل است','2026-08-15 19:29:32','2026-08-15 19:29:32'),(10,'case',1123,1,'بایت توی اسکن داخل دهانی درست ثبت نشده بوده ، برای همین دکتر قالبگیری مجدد دستی انجام داده که اون رو هم آپلود کردم. \r\nچون از فک پایین راضی بوده، چسبونده اما فک بالا رو راضی نبوده و گفته مجدد طراحی بشه. \r\ncase_1123_intraoral.zip اسکن اولیه داخل دهانی که بایت اش درست ثبت نشده\r\ncase_1123.zip قالب گیری با آلژینات با بایت صحیح','2026-08-17 12:14:25','2026-08-17 12:14:25'),(11,'case',1115,26,'لطفا مارژین چک شود','2026-08-20 01:44:25','2026-08-20 01:44:25'),(12,'case',1068,1,'این کار رو خود دکتر با اسکنرش اسکن کرده بود. \r\nطراحی کردیم و ساختیم و تحویل دادیم ، و گفت که :\r\nسلام وقت بخیر\r\nاین بیمارو مجدد اسکن کردیم براتون\r\nخواستیم تحویل بدیم مارجین روکش از سمت باکال یک میل کوتاه بود!','2026-08-23 13:22:40','2026-08-23 13:22:40'),(14,'case',1146,26,'اسکن مستقیم از اباتمنت!!','2026-08-25 21:45:49','2026-08-25 21:45:49'),(15,'case',1149,26,'قالب مستقیم از اباتمنت!!','2026-08-27 12:29:32','2026-08-27 12:29:32'),(16,'case',1150,26,'قالب مستقیم از اباتمنت!!','2026-08-27 12:30:10','2026-08-27 12:30:10'),(17,'case',1151,26,'قالب مستقیم از اباتمنت!!','2026-08-27 12:31:07','2026-08-27 12:31:07');
