INSERT INTO `users` VALUES (1,'admin','$2y$12$Qs8SyaEtzenAYp7NHeMFi.q0algCQ7p1TzObGBD1mJXaQZutY5uT6','مدیر سایت','admin@exolab.ir','09120889892','admin',1,NULL,NULL,1,0,1,'2026-09-01 01:34:01','2026-07-05 02:07:35','2026-09-01 01:34:01',NULL),(2,'hoseinizahra70@gmail.com','$2y$10$p4dN00EmPCn5CxD4vBxsdeyaZ.UdgSFtYzmws7ZpbtSjrrb/YloRO','زهرا حسینی','hoseinizahra70@gmail.com','09127727903','doctor',1,NULL,NULL,0,0,1,'2026-08-10 18:33:30','2026-06-07 15:19:10','2026-08-23 13:15:36',NULL),(3,'Rabiei@exolab.ir','$2y$10$nWIbCJ9ij9k8JZI9oV1Gru4jabucwElt04mgmvodHb2WK6g6ZSdma','احمدرضا ربیعی','Dr_Rabiei@exolab.ir','09129351238','doctor',1,NULL,NULL,0,0,1,NULL,'2026-07-03 15:54:42','2026-08-23 13:15:36','تو کارهای قالب \r\nfrom morgin = 0\r\ncement gap = .2\r\nradial and axial gap = .1\r\nتوی کارهایی که با اسکنر داخل دهانی تهیه شدن :\r\nfrom morgin = 0.2\r\ncement gap = .08\r\nradial and axial gap = .1\r\nهمه جاهایی که آندرکات دارن باید با دادن گپ اضافی، پوشش داده بشن.\r\nکانتکت ها جوری بسته بشه که گیر غذایی بوجود نیاد.\r\nپونتیک ها یک میلیمتر زیر لثه کار شود\r\nآناتومی ترجیحا Generic و یا smoothed generic \r\nدر مواردی که حباب داخل قالب بود یا بزاق و مواردی در کست یا اسکن بود، به نحوی طراحی بکنید که اولویت اول ، سهولت و سرعت بالای تحویل کار توسط پزشک باشه. (شل بشه روکش بهتر از اینه که زمان دکتر گرفته بشه)'),(10,'dr_sahar_mohebbi@exolab.ir','$2y$10$ZAjM1NIufwHztpQP9gSKi.J8rYr8ZwdqNdECmXV7QfZfGEU4pcSh2','سحر محبی','dr_sahar_mohebbi@exolab.ir','09120993858','doctor',1,NULL,NULL,0,0,1,NULL,'2026-07-08 15:40:51','2026-08-23 13:15:36','درمانگاه ایمانعلیزاده قائمیه _ خانم خوش نظر'),(11,'tehrandent','$2y$10$WSRRWPcgIERZHIlPpShSVehu721K2KVnRHbQKJfCQwnoGH8RtxGZ6','تهران دنت','tehrandent@exolab.ir','09056188565','outsource_lab',NULL,NULL,NULL,0,0,0,NULL,'2026-07-10 16:16:20','2026-08-26 22:39:46',NULL),(12,'Dr_pouya@exolab.ir','$2y$12$5BFU7MSQePQ3jM/DN5rf9eC73CkNTAwQSDSu8TItjaWvruqd.qING','میلاد پوریا','Dr_pouya@exolab.ir','09128338892','doctor',1,NULL,NULL,0,0,1,'2026-08-11 09:47:11','